// ADR-044: Overflow helper functions
#include <limits.h>

/* ADR-044 / Issue #94: the second parameter is the WIDER type, not the value type.
   Narrowing it first would let an out-of-range operand truncate INTO range and defeat
   the check: cnx_clamp_add_u8(0, 256) must saturate to 255, but (uint8_t)256 is 0, so a
   uint8_t parameter would return 0 -- the opposite of saturation. */

static inline uint32_t cnx_clamp_add_u32(uint32_t a, uint64_t b) {
    if (b > (uint64_t)(UINT32_MAX - a)) return UINT32_MAX;
    return (uint32_t)(a + (uint32_t)b);
}

// test-execution
// Issue #1131: the generated strlen cache shadowed a user global.
//
// The cache was named `_<var>_len`, a shape a user is allowed to declare. With a
// global `_msg_len` in scope, the generated `size_t _msg_len = strlen(msg);`
// shadowed it, and BOTH operands of `msg.value_char_count + _msg_len` resolved to the
// shadowing local — the sum became 5 + 5 rather than 5 + 42.
//
// It produced a wrong value with gcc -std=c99 -Wall -Wextra completely clean and
// the transpiler exiting 0, which is the worst failure mode this project has.
//
// ADR-063 part 2 renames the cache to `cnx_len_<var>`, in a namespace E0202
// forbids the user from declaring, so the collision is unrepresentable.
const uint8_t _msg_len = 42U;

uint32_t count(void) {
    const char msg[17] = "hello";
    uint32_t total = 0U;
    uint32_t cnx_len_msg = (uint32_t) strlen(msg);
    if (cnx_len_msg > 2) {
        total = cnx_clamp_add_u32(cnx_len_msg, _msg_len);
    }
    return total;
}

int main(void) {
    const uint32_t total = count();
    if (total != 47) {
        return 1U;
    }
    return 0U;
}
